result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "rawhttp.py", "content": """"Minimal HTTP/1.0 static file server built on raw sockets.

No http.server / http.client usage -- just socket, threading, os, mimetypes.
"""

import mimetypes
import os
import posixpath
import socket
import threading
from urllib.parse import unquote, urlsplit

CRLF = "\r\n"
SERVER_NAME = "rawhttp/1.0"


class _HTTPError(Exception):
    def __init__(self, status, reason, extra_headers=None):
        super().__init__(reason)
        self.status = status
        self.reason = reason
        self.extra_headers = extra_headers or []


def _status_reason(code):
    return {
        200: "OK",
        403: "Forbidden",
        404: "Not Found",
        405: "Method Not Allowed",
        400: "Bad Request",
    }.get(code, "Unknown")


def _send_response(conn, status, body=b"", content_type=None, extra_headers=None):
    lines = ["HTTP/1.0 %d %s" % (status, _status_reason(status))]
    lines.append("Server: %s" % SERVER_NAME)
    if content_type is not None:
        lines.append("Content-Type: %s" % content_type)
    lines.append("Content-Length: %d" % len(body))
    for h in extra_headers or []:
        lines.append("%s: %s" % h)
    lines.append("Connection: close")
    head = CRLF.join(lines).encode("iso-8859-1") + b"\r\n\r\n"
    conn.sendall(head)
    # HEAD requests are signalled by the caller passing a marker via extra_headers;
    # the caller never hands us a body for HEAD.
    if body:
        conn.sendall(body)


def _resolve_path(root, url_path):
    """Map a URL path onto the filesystem root safely.

    Returns an absolute filesystem path. Raises _HTTPError(403) if the
    normalized path would escape the root.
    """
    # Decode percent-encoding first, so %2e%2e%2f becomes ../ before checks.
    decoded = unquote(url_path)

    # Normalize as a POSIX relative path; collapse .. and . segments.
    normalized = posixpath.normpath("/" + decoded).lstrip("/")

    candidate = os.path.join(root, *normalized.split("/")) if normalized else root
    real_candidate = os.path.realpath(candidate)
    real_root = os.path.realpath(root)

    if not (real_candidate == real_root or real_candidate.startswith(real_root + os.sep)):
        raise _HTTPError(403)

    return real_candidate


def _guess_type(path):
    ctype, _ = mimetypes.guess_type(path)
    return ctype or "application/octet-stream"


def _handle_request(method, target, root):
    """Return (status, headers_extra, body_or_None) for a parsed request."""
    if method not in ("GET", "HEAD"):
        raise _HTTPError(
            405,
            extra_headers=[("Allow", "GET, HEAD")],
        )

    path_only = urlsplit(target).path

    fs_path = _resolve_path(root, path_only)

    if os.path.isdir(fs_path):
        index = os.path.join(fs_path, "index.html")
        if not os.path.isfile(index):
            raise _HTTPError(404)
        fs_path = index

    if not os.path.isfile(fs_path):
        raise _HTTPError(404)

    with open(fs_path, "rb") as f:
        body = f.read()

    return 200, [], body


def _read_until_headers(rfile):
    """Read from a socket file object until end of headers; return bytes."""
    data = bytearray()
    while b"\r\n\r\n" not in data:
        chunk = rfile.readline()
        if not chunk:
            break
        data.extend(chunk)
        if len(data) > 65536:
            break
    return bytes(data)


def _handle_connection(conn, addr, root):
    try:
        conn.settimeout(10)
        rfile = conn.makefile("rb")

        header_bytes = _read_until_headers(rfile)
        if not header_bytes:
            return

        try:
            text = header_bytes.decode("iso-8859-1")
            request_line = text.split(CRLF, 1)[0]
            parts = request_line.split()
            method, target = parts[0].upper(), parts[1]
        except (IndexError, UnicodeDecodeError):
            _send_response(conn, 400)
            return

        try:
            status, extra_headers, body = _handle_request(method, target, root)
            if method == "HEAD":
                _send_response(conn, status, b"", _guess_type_for_head(target, root), extra_headers)
            else:
                _send_response(conn, status, body, _guess_type(target), extra_headers)
        except _HTTPError as e:
            if method == "HEAD":
                _send_response(conn, e.status, b"", None, e.extra_headers)
            else:
                body = (_status_reason(e.status)).encode() + b"\n"
                _send_response(conn, e.status, body, "text/plain", e.extra_headers)
    except (ConnectionError, socket.timeout, OSError):
        pass
    finally:
        try:
            conn.shutdown(socket.SHUT_RDWR)
        except OSError:
            pass
        conn.close()


def _guess_type_for_head(target, root):
    # For HEAD we must report Content-Type/Length without needing the body,
    # but since we already resolved the file we can just stat it lazily.
    # Simplest correct approach: resolve again and guess from filename.
    try:
        path_only = urlsplit(target).path
        fs_path = _resolve_path(root, path_only)
        if os.path.isdir(fs_path):
            fs_path = os.path.join(fs_path, "index.html")
        return _guess_type(fs_path)
    except _HTTPError:
        return "text/plain"


def serve(directory, port=0):
    """Start serving `directory` on the given port (default: ephemeral).

    Returns the actual bound port. Runs in a daemon thread.
    """
    root = os.path.abspath(directory)
    if not os.path.isdir(root):
        raise ValueError("not a directory: %r" % directory)

    sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    sock.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    sock.bind(("127.0.0.1", port))
    actual_port = sock.getsockname()[1]
    sock.listen(16)

    def accept_loop():
        while True:
            try:
                conn, addr = sock.accept()
            except OSError:
                return
            t = threading.Thread(
                target=_handle_connection, args=(conn, addr, root), daemon=True
            )
            t.start()

    threading.Thread(target=accept_loop, daemon=True).start()
    return actual_port
